# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe Timekeeping::ProjectionConsumer do
  let(:receipt_company) { create(:company) }
  let(:receipt_project) { create(:project, client: create(:client, company: receipt_company)) }
  let(:receipt_user) { create(:user).tap { |user| create(:employment, company: receipt_company, user:) } }

  def receipt_batch(version:)
    entry = TimekeepingSnapshots.entry(id: 80_101, company_id: receipt_company.id, version:,
                                       project_id: receipt_project.id, user_id: receipt_user.id)
    TimekeepingSnapshots.batch(TimekeepingSnapshots.item(entry, generation: 1, outbox_position: 5))
  end

  it "replays the first answer for the same key and batch after the flip and rejects a changed batch under that key" do
    key = SecureRandom.uuid
    TimekeepingOwnership.current.update!(generation: 2, handoff_step: "freeze", final_outbox_position: 10)
    first = described_class.call(batch: receipt_batch(version: 1), idempotency_key: key)
    expect([first.status, first.body.deep_stringify_keys]).to eq([200, { "applied" => 1, "ignored" => 0 }])

    # The flip ends the previous generation's window; a relay retry after a lost 200
    # must still get its first answer back rather than a 409.
    TimekeepingOwnership.current.update!(handoff_step: nil, final_outbox_position: nil)
    replay = described_class.call(batch: receipt_batch(version: 1), idempotency_key: key)
    reused = described_class.call(batch: receipt_batch(version: 2), idempotency_key: key)

    expect([replay.status, replay.body.deep_stringify_keys]).to eq([200, { "applied" => 1, "ignored" => 0 }])
    expect([reused.status, reused.body.deep_stringify_keys]).to eq([422, { "reason" => "idempotency_key_reused" }])
    expect(TimesheetEntry.find(80_101).version).to eq(1)
  end
end

RSpec.describe Timekeeping::ProjectionConsumer do
  let(:retry_company) { create(:company) }
  let(:retry_project) { create(:project, client: create(:client, company: retry_company)) }
  let(:retry_user) { create(:user).tap { |user| create(:employment, company: retry_company, user:) } }

  def retry_batch(generation:)
    entry = TimekeepingSnapshots.entry(id: 80_201, company_id: retry_company.id, version: 1,
                                       project_id: retry_project.id, user_id: retry_user.id)
    TimekeepingSnapshots.batch(TimekeepingSnapshots.item(entry, generation:))
  end

  it "does not store a 409 so a retry under the same key is evaluated again and applies" do
    key = SecureRandom.uuid
    TimekeepingOwnership.current.update!(generation: 2)

    refused = described_class.call(batch: retry_batch(generation: 1), idempotency_key: key)
    expect(refused.status).to eq(409)
    expect(TimesheetEntry.with_discarded.where(id: 80_201)).to be_empty

    retried = described_class.call(batch: retry_batch(generation: 2), idempotency_key: key)

    expect([retried.status, retried.body.deep_stringify_keys]).to eq([200, { "applied" => 1, "ignored" => 0 }])
    expect(TimesheetEntry.find(80_201).version).to eq(1)
  end

  it "prunes expired receipts stored under other keys and keeps live ones on a keyed delivery" do
    receipt_attributes = { company_ids: [retry_company.id], actor: "timekeeping", request_digest: "digest",
                           response_status: 200, response_body: { "applied" => 1, "ignored" => 0 } }
    expired = EntrySnapshotReceipt.create!(**receipt_attributes, key: "expired-key", created_at: 2.days.ago,
                                           expires_at: 1.day.ago)
    live = EntrySnapshotReceipt.create!(**receipt_attributes, key: "live-key", created_at: 1.hour.ago,
                                        expires_at: 23.hours.from_now)

    result = described_class.call(batch: retry_batch(generation: 1), idempotency_key: SecureRandom.uuid)

    expect(result.status).to eq(200)
    expect(EntrySnapshotReceipt.where(id: expired.id)).not_to exist
    expect(EntrySnapshotReceipt.where(id: live.id)).to exist
  end
end

RSpec.describe Timekeeping::SnapshotDeliveryReceipts, "decimal fingerprints" do
  let(:decimal_receipt_answer) { Timekeeping::ProjectionConsumer::Result.new(status: 200, body: { "applied" => 1, "ignored" => 0 }) }

  def decimal_receipt_body(rate)
    %({"schema_version":1,"snapshots":[{"entry":{"duration":30.0,"source_metadata":{"rate":#{rate}}}}]})
  end

  def decimal_receipt(key, batch)
    described_class.new(key:, batch:, company_ids: [1])
  end

  it "replays a receipt stored when decimals were read as Floats for the same body read with exact decimals" do
    key = SecureRandom.uuid
    body = decimal_receipt_body("1.25")
    decimal_receipt(key, JSON.parse(body)).store(decimal_receipt_answer)

    replay = decimal_receipt(key, JSON.parse(body, decimal_class: BigDecimal)).stored_answer

    expect(replay&.status).to eq(200)
  end

  it "tells a JSON number from a JSON string of the same digits, and a fine decimal from its rounded Float" do
    key = SecureRandom.uuid
    decimal_receipt(key, JSON.parse(decimal_receipt_body("1.00000000000000000001"), decimal_class: BigDecimal))
      .store(decimal_receipt_answer)

    as_string = decimal_receipt(key, JSON.parse(decimal_receipt_body('"1.00000000000000000001"'), decimal_class: BigDecimal))
    rounded = decimal_receipt(key, JSON.parse(decimal_receipt_body("1.0"), decimal_class: BigDecimal))

    expect([as_string.stored_answer.status, rounded.stored_answer.status]).to eq([422, 422])
  end
end
